<?php
namespace App\Policies;use App\Models\{User,Chargeback};final class ChargebackPolicy{private function a(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','FINANCE_ADMIN','FINANCE_OPERATOR','RECONCILIATION_ANALYST'])->exists();}public function viewAny(User$u):bool{return$this->a($u);}public function view(User$u,Chargeback$m):bool{return$this->a($u);}public function create(User$u):bool{return$this->a($u);}public function update(User$u,Chargeback$m):bool{return$this->a($u);}public function delete(User$u,Chargeback$m):bool{return false;}}
